def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(s: str) -> int | None:
        if s.isascii() and s.isdigit():
            return int(s)
        return None

    for idx, op in enumerate(ops):
        tokens = op.split(" ")
        if not tokens or any(t == "" for t in tokens):
            rejected.append(idx)
            continue

        verb = tokens[0]

        if verb == "open" and len(tokens) == 3:
            acct, raw_amt = tokens[1], tokens[2]
            amt = parse_amount(raw_amt)
            if amt is not None and acct not in balances:
                balances[acct] = amt
                history.append(("open", acct))
            else:
                rejected.append(idx)

        elif verb == "deposit" and len(tokens) == 3:
            acct, raw_amt = tokens[1], tokens[2]
            amt = parse_amount(raw_amt)
            if amt is not None and amt > 0 and acct in balances:
                balances[acct] += amt
                history.append(("deposit", acct, amt))
            else:
                rejected.append(idx)

        elif verb == "withdraw" and len(tokens) == 3:
            acct, raw_amt = tokens[1], tokens[2]
            amt = parse_amount(raw_amt)
            if (
                amt is not None
                and amt > 0
                and acct in balances
                and acct not in frozen
                and balances[acct] >= amt
            ):
                balances[acct] -= amt
                history.append(("withdraw", acct, amt))
            else:
                rejected.append(idx)

        elif verb == "transfer" and len(tokens) == 4:
            src, dst, raw_amt = tokens[1], tokens[2], tokens[3]
            amt = parse_amount(raw_amt)
            if (
                amt is not None
                and amt > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amt
            ):
                balances[src] -= amt
                balances[dst] += amt
                history.append(("transfer", src, dst, amt))
            else:
                rejected.append(idx)

        elif verb == "freeze" and len(tokens) == 2:
            acct = tokens[1]
            if acct in balances and acct not in frozen:
                frozen.add(acct)
                history.append(("freeze", acct))
            else:
                rejected.append(idx)

        elif verb == "unfreeze" and len(tokens) == 2:
            acct = tokens[1]
            if acct in balances and acct in frozen:
                frozen.remove(acct)
                history.append(("unfreeze", acct))
            else:
                rejected.append(idx)

        elif verb == "undo" and len(tokens) == 1:
            if not history:
                rejected.append(idx)
            else:
                last = history.pop()
                kind = last[0]
                if kind == "open":
                    del balances[last[1]]
                elif kind == "deposit":
                    balances[last[1]] -= last[2]
                elif kind == "withdraw":
                    balances[last[1]] += last[2]
                elif kind == "transfer":
                    balances[last[1]] += last[3]
                    balances[last[2]] -= last[3]
                elif kind == "freeze":
                    frozen.remove(last[1])
                elif kind == "unfreeze":
                    frozen.add(last[1])

        else:
            rejected.append(idx)

    return balances, rejected
